> node = _tail_ (node); 
> else if _only head_ (node) _is not marked nor is it atom mark head_ (node); 
> node = _head_ (node); 
> else if _both head_ (node) _and tail_ (node) _are not marked nor are they atoms mark both head_ (node) _and tail_ (node); 
> push( _tail_ (node)); 
> node = _head_ (node); 
